-- Immutable CloudTMS TEST ownership, ACL, and default-privilege snapshot.
-- Applied last so browser and service-role authority exactly matches the verified TEST boundary.
-- Supabase platform-owned supabase_admin default privileges are deliberately excluded:
-- application releases must not reproduce or depend on platform-superuser defaults.

\set ON_ERROR_STOP on
set search_path = pg_catalog, public, extensions;

alter schema "private" owner to "postgres";
revoke all privileges on schema "private" from PUBLIC, anon, authenticated, service_role, postgres;
grant CREATE on schema "private" to "postgres";
grant USAGE on schema "private" to "postgres";
grant USAGE on schema "private" to "service_role";
alter schema "public" owner to "pg_database_owner";
revoke all privileges on schema "public" from PUBLIC, anon, authenticated, service_role, postgres;
grant USAGE on schema "public" to PUBLIC;
grant USAGE on schema "public" to "anon";
grant USAGE on schema "public" to "authenticated";
grant CREATE on schema "public" to "pg_database_owner";
grant USAGE on schema "public" to "pg_database_owner";
